import { App, TFile } from 'obsidian';
import { addPaperToGraph, loadSinglePaper } from '../DataLoader';
import { GraphData, PaperNode } from '../types/Paper';

/**
 * Tests for dynamic paper ingestion (Phase 4 capability)
 */
describe('DataLoader - Dynamic Paper Ingestion', () => {
  let mockApp: App;
  let mockGraphData: GraphData;
  let mockPaperMap: Map<string, PaperNode>;

  beforeEach(() => {
    // Mock Obsidian App
    mockApp = {
      vault: {
        read: jest.fn(),
      },
    } as unknown as App;

    // Create mock graph data
    mockGraphData = {
      nodes: [
        {
          id: 'paper-1',
          title: 'Paper 1',
          path: 'papers/paper-1.md',
          dimensions: {
            connectivity: 0.5,
            conceptual_depth: 0.5,
            temporal: 0.5,
            cross_domain: 5,
            completion: 50,
            recency: 0.5,
            semantic_similarity: 0.0,
            similar_papers: [],
          },
        },
      ],
      edges: [],
      metadata: {
        totalPapers: 1,
        totalEdges: 0,
        avgConnectivity: 0.5,
        domainDistribution: { domain_5: 1 },
        loadedAt: Date.now(),
      },
    };

    // Create paper map
    mockPaperMap = new Map();
    for (const node of mockGraphData.nodes) {
      mockPaperMap.set(node.id, node);
    }
  });

  describe('loadSinglePaper', () => {
    it('should load a paper from file', async () => {
      const mockFile = {
        basename: 'test-paper',
        extension: 'md',
        path: 'papers/test-paper.md',
      } as unknown as TFile;

      const mockFrontmatter = `---
title: "Test Paper"
date: "2026-02-14"
connectivity: 0.7
conceptual_depth: 0.3
temporal: 0.9
cross_domain: 8
completion: 75
recency: 0.8
---`;

      (mockApp.vault.read as jest.Mock).mockResolvedValueOnce(mockFrontmatter);

      const paper = await loadSinglePaper(mockApp, mockFile);

      expect(paper).not.toBeNull();
      expect(paper?.id).toBe('test-paper');
      expect(paper?.title).toBe('Test Paper');
      expect(paper?.dimensions.connectivity).toBe(0.7);
    });

    it('should handle missing frontmatter gracefully', async () => {
      const mockFile = {
        basename: 'no-frontmatter',
        extension: 'md',
        path: 'papers/no-frontmatter.md',
      } as unknown as TFile;

      (mockApp.vault.read as jest.Mock).mockResolvedValueOnce('# No frontmatter content');

      const paper = await loadSinglePaper(mockApp, mockFile);

      expect(paper).not.toBeNull();
      expect(paper?.id).toBe('no-frontmatter');
      expect(paper?.title).toBe('no-frontmatter');
      expect(paper?.dimensions.connectivity).toBe(0.5); // Default value
    });

    it('should apply default dimensions when not specified', async () => {
      const mockFile = {
        basename: 'minimal-paper',
        extension: 'md',
        path: 'papers/minimal-paper.md',
      } as unknown as TFile;

      const mockFrontmatter = `---
title: "Minimal Paper"
---`;

      (mockApp.vault.read as jest.Mock).mockResolvedValueOnce(mockFrontmatter);

      const paper = await loadSinglePaper(mockApp, mockFile);

      expect(paper?.dimensions).toBeDefined();
      expect(paper?.dimensions.connectivity).toBeDefined();
      expect(paper?.dimensions.completion).toBeGreaterThanOrEqual(0);
      expect(paper?.dimensions.completion).toBeLessThanOrEqual(100);
    });
  });

  describe('addPaperToGraph', () => {
    it('should add a new paper to graph', () => {
      const newPaper: PaperNode = {
        id: 'paper-2',
        title: 'New Paper',
        path: 'papers/paper-2.md',
        dimensions: {
          connectivity: 0.6,
          conceptual_depth: 0.4,
          temporal: 0.7,
          cross_domain: 6,
          completion: 60,
          recency: 0.7,
          semantic_similarity: 0.0,
          similar_papers: [{ title: 'paper-1', score: 0.8 }],
        },
      };

      const updated = addPaperToGraph(mockGraphData, newPaper, mockPaperMap);

      expect(updated.nodes.length).toBe(mockGraphData.nodes.length + 1);
      expect(updated.metadata.totalPapers).toBe(2);
      expect(mockPaperMap.has('paper-2')).toBe(true);
    });

    it('should update metadata when adding paper', () => {
      const newPaper: PaperNode = {
        id: 'paper-2',
        title: 'New Paper',
        path: 'papers/paper-2.md',
        dimensions: {
          connectivity: 0.8,
          conceptual_depth: 0.6,
          temporal: 0.9,
          cross_domain: 10,
          completion: 80,
          recency: 0.9,
          semantic_similarity: 0.0,
          similar_papers: [],
        },
      };

      const updated = addPaperToGraph(mockGraphData, newPaper, mockPaperMap);

      expect(updated.metadata.avgConnectivity).toBeGreaterThan(mockGraphData.metadata.avgConnectivity);
      expect(updated.metadata.loadedAt).toBeGreaterThanOrEqual(Date.now() - 1000);
    });

    it('should not add duplicate papers', () => {
      const duplicate = mockGraphData.nodes[0];

      const updated = addPaperToGraph(mockGraphData, duplicate, mockPaperMap);

      expect(updated.nodes.length).toBe(mockGraphData.nodes.length);
    });

    it('should create edges for related papers', () => {
      const relatedPaper: PaperNode = {
        id: 'paper-2',
        title: 'Related Paper',
        path: 'papers/paper-2.md',
        dimensions: {
          connectivity: 0.5,
          conceptual_depth: 0.5,
          temporal: 0.5,
          cross_domain: 5,
          completion: 50,
          recency: 0.5,
          semantic_similarity: 0.0,
          similar_papers: [{ title: 'Paper 1', paperId: 'paper-1', score: 0.9 }],
        },
      };

      const updated = addPaperToGraph(mockGraphData, relatedPaper, mockPaperMap);

      expect(updated.edges.length).toBeGreaterThan(mockGraphData.edges.length);
      const newEdge = updated.edges[updated.edges.length - 1];
      expect(newEdge.similarity).toBeCloseTo(0.9, 1);
    });
  });

  describe('dynamic ingestion performance', () => {
    it('should handle 10 sequential paper additions', () => {
      const startTime = Date.now();
      let currentGraph = mockGraphData;

      for (let i = 0; i < 10; i++) {
        const newPaper: PaperNode = {
          id: `paper-${i + 2}`,
          title: `Paper ${i + 2}`,
          path: `papers/paper-${i + 2}.md`,
          dimensions: {
            connectivity: Math.random(),
            conceptual_depth: Math.random(),
            temporal: Math.random(),
            cross_domain: Math.floor(Math.random() * 10) + 1,
            completion: Math.floor(Math.random() * 100),
            recency: Math.random(),
            semantic_similarity: 0.0,
            similar_papers: [],
          },
        };

        currentGraph = addPaperToGraph(currentGraph, newPaper, mockPaperMap);
      }

      const elapsedMs = Date.now() - startTime;

      expect(currentGraph.nodes.length).toBe(mockGraphData.nodes.length + 10);
      expect(elapsedMs).toBeLessThan(500); // Should complete in < 500ms
    });

    it('should maintain metadata accuracy with many additions', () => {
      let currentGraph = mockGraphData;

      for (let i = 0; i < 50; i++) {
        const newPaper: PaperNode = {
          id: `paper-${i + 2}`,
          title: `Paper ${i + 2}`,
          path: `papers/paper-${i + 2}.md`,
          dimensions: {
            connectivity: 0.5 + Math.random() * 0.3,
            conceptual_depth: Math.random(),
            temporal: Math.random(),
            cross_domain: 5 + Math.floor(Math.random() * 5),
            completion: 50 + Math.floor(Math.random() * 40),
            recency: Math.random(),
            semantic_similarity: 0.0,
            similar_papers: [],
          },
        };

        currentGraph = addPaperToGraph(currentGraph, newPaper, mockPaperMap);
      }

      // Verify metadata is consistent
      expect(currentGraph.metadata.totalPapers).toBe(51);
      expect(currentGraph.nodes.length).toBe(51);
      expect(currentGraph.metadata.avgConnectivity).toBeGreaterThan(0);
      expect(currentGraph.metadata.avgConnectivity).toBeLessThan(1);
    });
  });

  describe('dimension handling', () => {
    it('should clamp dimensions to valid ranges', async () => {
      const mockFile = {
        basename: 'out-of-range',
        extension: 'md',
        path: 'papers/out-of-range.md',
      } as unknown as TFile;

      const mockFrontmatter = `---
title: "Out of Range"
connectivity: 1.5
temporal: -0.5
cross_domain: 100
completion: 150
recency: 2.0
---`;

      (mockApp.vault.read as jest.Mock).mockResolvedValueOnce(mockFrontmatter);

      const paper = await loadSinglePaper(mockApp, mockFile);

      expect(paper?.dimensions.connectivity).toBeGreaterThanOrEqual(0);
      expect(paper?.dimensions.connectivity).toBeLessThanOrEqual(1);
      expect(paper?.dimensions.temporal).toBeGreaterThanOrEqual(0);
      expect(paper?.dimensions.temporal).toBeLessThanOrEqual(1);
      expect(paper?.dimensions.cross_domain).toBeGreaterThanOrEqual(1);
      expect(paper?.dimensions.cross_domain).toBeLessThanOrEqual(15);
      expect(paper?.dimensions.completion).toBeGreaterThanOrEqual(0);
      expect(paper?.dimensions.completion).toBeLessThanOrEqual(100);
    });
  });
});

