import { OllamaEmbeddingService } from './OllamaEmbeddingService';

export class ReasoningInferenceEngine {
  private ollama = new OllamaEmbeddingService();

  async generateChainFromPattern(decisionText: string): Promise<ReasoningChain> {
    try {
      // Get embedding for current decision
      const targetEmbedding = await this.ollama.embed(decisionText);

      // Load all existing decisions
      const allDecisions = await this.vault.loadAllDecisions();

      // Compute similarity to all existing decisions
      const similarities = await Promise.all(
        allDecisions.map(async (decision) => ({
          decision,
          similarity: this.ollama.cosineSimilarity(
            targetEmbedding,
            await this.ollama.embed(decision.title + ' ' + (decision.rationale || ''))
          ),
        }))
      );

      // Find 3 most similar decisions
      const topThree = similarities
        .sort((a, b) => b.similarity - a.similarity)
        .slice(0, 3);

      // Extract reasoning patterns from similar decisions
      const patterns = topThree
        .map(({ decision, similarity }) => ({
          reasoning: decision.reasoning_chain || [],
          weight: similarity,
        }));

      // Generate chain based on weighted patterns
      const chain = this.generateChainFromPatterns(patterns, decisionText);

      // Set confidence based on max similarity
      chain.confidence = Math.max(...topThree.map(t => t.similarity));

      return chain;

    } catch (error) {
      console.error('Semantic inference failed:', (error as Error).message);
      // Fallback to basic template
      return this.generateBasicChain(decisionText);
    }
  }

  private generateChainFromPatterns(patterns: any[], decisionText: string): ReasoningChain {
    const steps: string[] = [];

    // Analyze decision text to determine type
    const type = this.detectReasoningType(decisionText);

    // Extract weighted patterns and merge
    for (const pattern of patterns) {
      for (const step of pattern.reasoning || []) {
        if (step && !steps.includes(step)) {
          steps.push(step);
        }
      }
    }

    // Ensure reasonable number of steps
    if (steps.length === 0) {
      steps.push('Analyzed the decision context');
      steps.push('Evaluated available approaches');
      steps.push('Selected most suitable option');
    }

    if (steps.length > 5) {
      steps.length = 5;
    }

    return {
      steps,
      reasoning_type: type,
      confidence: 0.7,  // Will be updated by caller
      assumptions: this.extractAssumptions(decisionText),
      timestamp: new Date().toISOString(),
    };
  }

  private generateBasicChain(decisionText: string): ReasoningChain {
    return {
      steps: [
        'Analyzed decision context',
        'Evaluated alternatives',
        'Selected best approach',
      ],
      reasoning_type: this.detectReasoningType(decisionText),
      confidence: 0.5,  // Lower confidence for fallback
      assumptions: this.extractAssumptions(decisionText),
      timestamp: new Date().toISOString(),
    };
  }

  private detectReasoningType(text: string): string {
    if (text.includes('research') || text.includes('evidence')) return 'research';
    if (text.includes('pattern') || text.includes('experience')) return 'pattern';
    if (text.includes('intuition') || text.includes('sense')) return 'intuition';
    if (text.includes('convention') || text.includes('standard')) return 'convention';
    return 'hybrid';
  }

  private extractAssumptions(text: string): string[] {
    const assumptions: string[] = [];
    if (text.includes('assume')) {
      assumptions.push('Assumptions from decision context');
    }
    return assumptions;
  }
}
```

