export class OllamaEmbeddingService {
  private ollamaUrl = 'http://localhost:11434/api/embed';
  private model = 'nomic-embed-text';
  private cache = new Map<string, number[]>();  // LRU cache

  async embed(text: string): Promise<number[]> {
    // Check cache first
    if (this.cache.has(text)) {
      return this.cache.get(text)!;
    }

    try {
      const response = await fetch(this.ollamaUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          model: this.model,
          prompt: text,
        }),
      });

      if (!response.ok) {
        throw new Error(`Ollama API error: ${response.statusText}`);
      }

      const data = await response.json();
      const embedding = data.embedding;

      // Cache result
      if (this.cache.size > 1000) {
        const firstKey = this.cache.keys().next().value;
        this.cache.delete(firstKey);  // Simple LRU
      }
      this.cache.set(text, embedding);

      return embedding;
    } catch (err) {
      console.error('Failed to get embedding:', (err as Error).message);
      throw new Error(
        `Failed to get Ollama embedding. Is Ollama running on ${this.ollamaUrl}?\n` +
        `Start Ollama with: ollama serve`
      );
    }
  }

  // Compute cosine similarity between two vectors
  cosineSimilarity(vecA: number[], vecB: number[]): number {
    let dotProduct = 0;
    let magnitudeA = 0;
    let magnitudeB = 0;

    for (let i = 0; i < vecA.length; i++) {
      dotProduct += vecA[i] * vecB[i];
      magnitudeA += vecA[i] * vecA[i];
      magnitudeB += vecB[i] * vecB[i];
    }

    magnitudeA = Math.sqrt(magnitudeA);
    magnitudeB = Math.sqrt(magnitudeB);

    if (magnitudeA === 0 || magnitudeB === 0) return 0;

    return dotProduct / (magnitudeA * magnitudeB);
  }
}
```

