   187→      }
   188→    } catch (error) {
   189→      console.error('Failed to load dashboard data:', error);
   190→    }
   191→  }
   192→
   193→  /**
   194→   * Render all dashboard metrics
   195→   */
   196→  private async render(): Promise<void> {
   197→    this.renderContent();
   198→  }
   199→
   200→  /**
   201→   * Render content for active tab
   202→   */
   203→  private renderContent(): void {
   204→    const contentEl = document.getElementById('dashboard-content');
   205→    if (!contentEl) return;
   206→
   207→    contentEl.innerHTML = '';
   208→
   209→    switch (this.activeTab) {
