   223→        this.renderImpactDistribution(contentEl);
   224→        break;
   225→      case 'velocity':
   226→        this.renderDecisionVelocity(contentEl);
   227→        break;
   228→    }
   229→  }
   230→
   231→  /**
   232→   * Render Confidence Distribution histogram
   233→   */
   234→  private renderConfidenceDistribution(parentEl: HTMLElement): void {
   235→    const section = parentEl.createDiv('metric-section');
   236→    section.createEl('h3', { text: 'Confidence Distribution' });
   237→
   238→    const data = DashboardMetricsComputer.computeConfidenceDistribution(this.decisions);
   239→
   240→    if (window.Chart) {
   241→      const canvas = section.createEl('canvas');
   242→      this.createBarChart(canvas, {
   243→        labels: data.labels,
   244→        datasets: [
   245→          {
   246→            label: 'Decision Count',
   247→            data: data.data,
   248→            backgroundColor: '#3b82f6',
   249→          },
   250→        ],
   251→      });
   252→    } else {
   253→      this.renderHistogramTable(section, data);
   254→    }
   255→
   256→    const stats = section.createDiv('metric-stats');
   257→    const avgConfidence =
   258→      this.decisions.reduce((sum, d) => sum + (d.confidence_score || 0), 0) /
   259→      this.decisions.length;
   260→    stats.createEl('p', {
   261→      text: `Average Confidence: ${(avgConfidence * 100).toFixed(1)}%`,
   262→    });
   263→  }
   264→
   265→  /**
   266→   * Render Reasoning Type Breakdown pie chart
   267→   */
   268→  private renderReasoningBreakdown(parentEl: HTMLElement): void {
   269→    const section = parentEl.createDiv('metric-section');
   270→    section.createEl('h3', { text: 'Reasoning Type Breakdown' });
   271→
   272→    const data = DashboardMetricsComputer.computeReasoningBreakdown(this.decisions);
   273→
   274→    if (window.Chart) {
   275→      const canvas = section.createEl('canvas');
   276→      this.createPieChart(canvas, {
   277→        labels: data.labels,
   278→        datasets: [
   279→          {
   280→            data: data.data,
   281→            backgroundColor: data.backgroundColor,
   282→          },
   283→        ],
