      this.renderReasoningBreakdown(contentEl);
      break;
    case 'contradiction':
      this.renderContradictionTrend(contentEl);
      break;
    case 'quality':
      this.renderQualityRanking(contentEl);
      break;
    case 'impact':
      this.renderImpactDistribution(contentEl);
