import { App, PluginSettingTab, Setting, Notice, SearchComponent } from 'obsidian';
import { Decision } from '../types/Decision';
import { SurrealDBClient } from '../services/SurrealDBClient';
import { VaultBridge } from '../services/VaultBridge';
import { ReasoningFlowchart } from '../visualizations/ReasoningFlowchart';
import { CascadeGraph } from '../visualizations/CascadeGraph';
import { ContradictionMatrix } from '../visualizations/ContradictionMatrix';
import { DecisionQualityScorer, QualityScoreBreakdown } from '../services/DecisionQualityScorer';
import { ReasoningInferenceEngine } from '../services/ReasoningInference';
import { CascadeInferenceEngine, DecisionImpact } from '../services/CascadeInference';
import { SemanticContradictionDetector } from '../services/SemanticContradictionDetector';

/**
 * Decision Explorer Panel for Phase 4
 *
 * Main UI component for exploring decisions and their reasoning chains.
 * Provides:
 * - Decision search with autocomplete
 * - Reasoning chain visualization
 * - Cascade impact analysis
 * - Contradiction detection
 * - Metadata display
 *
 * @example
 * const explorer = new DecisionExplorer(app, surrealClient, vaultBridge);
 * explorer.loadPanel(containerElement);
 */
export class DecisionExplorer {
  private app: App;
  private surrealClient: SurrealDBClient;
  private vaultBridge: VaultBridge;
  private decisions: Map<string, Decision> = new Map();
  private selectedDecision: Decision | null = null;
  private containerEl: HTMLElement | null = null;

  constructor(app: App, surrealClient: SurrealDBClient, vaultBridge: VaultBridge) {
    this.app = app;
    this.surrealClient = surrealClient;
    this.vaultBridge = vaultBridge;
  }

  /**
   * Load all decisions from vault
   */
  async loadDecisions(): Promise<void> {
    try {
      this.decisions = await this.vaultBridge.loadAllDecisions();
      console.log(`Loaded ${this.decisions.size} decisions for explorer`);
    } catch (error) {
      console.error('Error loading decisions:', error);
      new Notice('Failed to load decisions from vault');
    }
  }

  /**
   * Create and attach the explorer panel to a container
   */
  loadPanel(containerEl: HTMLElement): void {
    this.containerEl = containerEl;
    containerEl.empty();
    containerEl.addClass('decision-explorer-panel');

    // Create main sections
    this.createSearchSection(containerEl);
    this.createMetadataSection(containerEl);
    this.createActionButtons(containerEl);
  }

  /**
   * Create search and selection section
   */
  private createSearchSection(containerEl: HTMLElement): void {
    const searchDiv = containerEl.createDiv('decision-search-section');
    searchDiv.style.paddingBottom = '20px';
    searchDiv.style.borderBottom = '1px solid #ddd';

    // Header
    const header = searchDiv.createEl('h3');
    header.textContent = 'Decision Explorer';
    header.style.marginBottom = '15px';

    // Search input
    const searchContainer = searchDiv.createDiv('decision-search-container');
    const input = searchContainer.createEl('input', { type: 'text' });
    input.placeholder = 'Search decisions...';
    input.style.width = '100%';
    input.style.padding = '8px 12px';
    input.style.border = '1px solid #ccc';
    input.style.borderRadius = '4px';
    input.style.marginBottom = '10px';
    input.style.fontFamily = 'inherit';

    // Results dropdown
    const resultsDiv = searchContainer.createDiv('decision-results');
    resultsDiv.style.maxHeight = '300px';
    resultsDiv.style.overflow = 'auto';
    resultsDiv.style.border = '1px solid #ddd';
    resultsDiv.style.borderRadius = '4px';
    resultsDiv.style.backgroundColor = '#fff';
    resultsDiv.style.display = 'none';

    // Handle search input
    input.addEventListener('input', (e) => {
      const query = (e.target as HTMLInputElement).value.toLowerCase();

      if (query.length < 2) {
        resultsDiv.style.display = 'none';
        return;
      }

      resultsDiv.empty();
      resultsDiv.style.display = 'block';

      // Search decisions
      let count = 0;
      for (const [id, decision] of this.decisions) {
        if (
          decision.title.toLowerCase().includes(query) ||
          id.toLowerCase().includes(query) ||
          decision.chosen_option.toLowerCase().includes(query)
        ) {
          if (count >= 10) break; // Limit results

          const resultItem = resultsDiv.createDiv('decision-result-item');
          resultItem.style.padding = '10px';
          resultItem.style.borderBottom = '1px solid #eee';
          resultItem.style.cursor = 'pointer';
          resultItem.style.fontSize = '0.9em';

          const titleSpan = resultItem.createEl('strong');
          titleSpan.textContent = decision.title;

          const idSpan = resultItem.createEl('div');
          idSpan.style.fontSize = '0.8em';
          idSpan.style.color = '#999';
          idSpan.textContent = id;

          const confidenceSpan = resultItem.createEl('span');
          confidenceSpan.style.float = 'right';
          confidenceSpan.style.fontSize = '0.8em';
          confidenceSpan.style.color = '#666';
          confidenceSpan.textContent = `${(decision.confidence_score * 100).toFixed(0)}%`;

          resultItem.onmouseenter = () => {
            resultItem.style.backgroundColor = '#f0f0f0';
          };
          resultItem.onmouseleave = () => {
            resultItem.style.backgroundColor = 'transparent';
          };

content.content:
150→
151→          resultItem.onclick = () => {
152→            this.selectDecision(decision);
153→            resultsDiv.style.display = 'none';
154→            input.value = '';
155→          };
156→
157→          count++;
158→        }
159→      }
160→
161→      if (count === 0) {
162→        const noResults = resultsDiv.createDiv();
163→        noResults.textContent = 'No decisions found';
164→        noResults.style.padding = '10px';
165→        noResults.style.color = '#999';
166→        noResults.style.textAlign = 'center';
167→      }
168→    });
169→
170→    // Recent decisions list
171→    const recentDiv = searchDiv.createDiv('decision-recent');
172→    recentDiv.style.marginTop = '15px';
173→
174→    const recentHeader = recentDiv.createEl('small');
175→    recentHeader.textContent = 'Recent Decisions';
176→    recentHeader.style.display = 'block';
177→    recentHeader.style.color = '#666';
178→    recentHeader.style.marginBottom = '8px';
179→    recentHeader.style.fontWeight = 'bold';
180→
181→    // Show 5 most recent
182→    const recent = Array.from(this.decisions.values())
183→      .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
184→      .slice(0, 5);
185→
186→    for (const decision of recent) {
187→      const item = recentDiv.createEl('button');
188→      item.textContent = decision.title;
189→      item.style.display = 'block';
190→      item.style.width = '100%';
191→      item.style.padding = '6px 8px';
192→      item.style.marginBottom = '4px';
193→      item.style.border = '1px solid #ddd';
194→      item.style.borderRadius = '3px';
195→      item.style.backgroundColor = '#f9f9f9';
196→      item.style.cursor = 'pointer';
197→      item.style.fontSize = '0.85em';
198→      item.style.textAlign = 'left';
199→
200→      item.onmouseenter = () => {
201→        item.style.backgroundColor = '#e8e8e8';
202→      };
203→      item.onmouseleave = () => {
204→        item.style.backgroundColor = '#f9f9f9';
205→      };
206→
207→      item.onclick = (e) => {
208→        e.preventDefault();
209→        this.selectDecision(decision);
210→      };
211→    }
212→  }
213→
214→  /**
215→   * Create metadata display section
216→   */
217→  private createMetadataSection(containerEl: HTMLElement): void {
218→    const metadataDiv = containerEl.createDiv('decision-metadata-section');
219→    metadataDiv.style.padding = '20px 0';
220→    metadataDiv.style.borderBottom = '1px solid #ddd';
221→
222→    metadataDiv.id = 'decision-metadata';
223→
224→    if (!this.selectedDecision) {
225→      const placeholder = metadataDiv.createDiv();
226→      placeholder.textContent = 'Select a decision to view details';
227→      placeholder.style.color = '#999';
228→      placeholder.style.textAlign = 'center';
229→      placeholder.style.padding = '40px 0';
230→      return;
231→    }
232→
233→    // Decision title
234→    const titleDiv = metadataDiv.createDiv();
235→    const titleEl = titleDiv.createEl('h4');
236→    titleEl.textContent = this.selectedDecision.title;
237→    titleEl.style.marginBottom = '10px';
238→
239→    // Key metadata
240→    const metaGrid = metadataDiv.createDiv('decision-meta-grid');
241→    metaGrid.style.display = 'grid';
242→    metaGrid.style.gridTemplateColumns = '1fr 1fr';
243→    metaGrid.style.gap = '10px';
244→    metaGrid.style.marginBottom = '15px';
245→
246→    // Chosen option
247→    const optionDiv = metaGrid.createDiv();
248→    optionDiv.innerHTML = `
249→      <small style="color: #666;">Chosen Option</small>
250→      <div style="font-weight: bold; margin-top: 4px;">${this.selectedDecision.chosen_option}</div>
251→    `;
252→
253→    // Reasoning type
254→    const typeDiv = metaGrid.createDiv();
255→    const typeBadge = typeDiv.createEl('small');
256→    typeBadge.textContent = 'Reasoning Type';
257→    typeBadge.style.display = 'block';
258→    typeBadge.style.color = '#666';
