        paperItem.style.backgroundColor = '#f0f8ff';
      };
    }
  } else {
    const noLinks = papersDiv.createDiv();
    noLinks.textContent = 'No related papers found';
    noLinks.style.color = '#999';
    noLinks.style.fontSize = '0.9em';
    noLinks.style.fontStyle = 'italic';
  }
}

