        const nodeData = DecisionNodeRenderer.decisionToNodeData(testDecision, { x: 0, y: 0, z: 0 });
        expect(nodeData.color).toBe(expectedHue);
      }
      console.log('✓ Color encoding by reasoning type: PASS');
