  });

  // ============================================================================
  // INTEGRATION TEST 4: UI Functional Tests
  // ============================================================================
  describe('4. UI Functional Integration', () => {
    test('4A: Related papers section rendering', () => {
      const testDecision: Decision = {
        id: 'decision-with-papers',
